/** Namespace every reply by its actual episode and publication choice. */
export const KQ_SOCIAL_CBD_X: Record<string, KqSocialNarrative> = Object.fromEntries(Object.entries(narratives).map(([id, narrative]) => [id, {
  ...narrative,
  comments: narrative.comments.map((message, index) => ({ ...message, id: `${id}-comment-${index}` })) as KqSocialNarrative["comments"],
  choices: Object.fromEntries(Object.entries(narrative.choices).map(([choiceId, choice]) => [choiceId, { ...choice, replies: choice.replies.map((message, index) => ({ ...message, id: `${id}-${choiceId}-reply-${index}` })) as typeof choice.replies }])),
  ...(narrative.continuations ? { continuations: Object.fromEntries(Object.entries(narrative.continuations).map(([choiceId, continuation]) => [choiceId, { ...continuation, comment: { ...continuation.comment, id: `${id}-after-${choiceId}` } }])) } : {}),
}]));
